# SPDX-License-Identifier: Apache-2.0
"""Derive pinned font-family data without network access or external packages."""

import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DIRECTORY = Path(__file__).resolve().parent
VERSION = "17.0.0"
SOURCES = [
    (
        "CaseFolding.txt",
        "https://www.unicode.org/Public/17.0.0/ucd/CaseFolding.txt",
        "ff8d8fefbf123574205085d6714c36149eb946d717a0c585c27f0f4ef58c4183",
    ),
    (
        "UnicodeData.txt",
        "https://www.unicode.org/Public/17.0.0/ucd/UnicodeData.txt",
        "2e1efc1dcb59c575eedf5ccae60f95229f706ee6d031835247d843c11d96470c",
    ),
    (
        "LICENSE.txt",
        "https://www.unicode.org/license.txt",
        "e7a93b009565cfce55919a381437ac4db883e9da2126fa28b91d12732bc53d96",
    ),
]


def digest(data):
    return hashlib.sha256(data).hexdigest()


def derive():
    sources = []
    for filename, url, expected in SOURCES:
        data = (DIRECTORY / filename).read_bytes()
        if digest(data) != expected:
            raise ValueError(f"Pinned Unicode input differs: {filename}")
        sources.append(
            {"file": filename, "url": url, "bytes": len(data), "sha256": expected}
        )

    maps = {status: {} for status in ["C", "S", "F"]}
    for line in (DIRECTORY / "CaseFolding.txt").read_text(encoding="utf-8").splitlines():
        fields = line.split("#", 1)[0].strip().split(";")
        if len(fields) < 3 or fields[1].strip() not in maps:
            continue
        scalar, status = int(fields[0], 16), fields[1].strip()
        if scalar in maps[status]:
            raise ValueError("Repeated case-fold entry")
        maps[status][scalar] = [int(value, 16) for value in fields[2].split()]
    assert all(len(value) == 1 for status in ["C", "S"] for value in maps[status].values())
    assert [len(maps[status]) for status in ["C", "S", "F"]] == [1481, 31, 104]
    assert not set(maps["C"]) & (set(maps["S"]) | set(maps["F"]))

    common = [[scalar, value[0]] for scalar, value in sorted(maps["C"].items())]
    runs, singles, index = [], [], 0
    while index < len(common):
        start, target = common[index]
        delta, length, stride = target - start, 1, 1
        for step in [1, 2]:
            end = index + 1
            while (
                end < len(common)
                and common[end][0] == common[end - 1][0] + step
                and common[end][1] - common[end][0] == delta
            ):
                end += 1
            if end - index > length:
                length, stride = end - index, step
        if length > 1:
            runs.append([start, common[index + length - 1][0], stride, delta])
        else:
            singles.append(common[index])
        index += length
    restored = dict(singles)
    for start, end, stride, delta in runs:
        for scalar in range(start, end + 1, stride):
            assert scalar not in restored
            restored[scalar] = scalar + delta
    assert restored == dict(common)

    categories = {name: [] for name in ["L", "M", "Nd"]}
    pending = None
    previous = -1
    for line in (DIRECTORY / "UnicodeData.txt").read_text(encoding="utf-8").splitlines():
        fields = line.split(";")
        scalar, category = int(fields[0], 16), fields[2]
        assert scalar > previous
        previous = scalar
        if fields[1].endswith(", First>"):
            assert pending is None
            pending = (scalar, category)
            continue
        start = scalar
        if fields[1].endswith(", Last>"):
            assert pending is not None and pending[1] == category
            start, pending = pending[0], None
        else:
            assert pending is None
        name = category[0] if category[0] in ["L", "M"] else "Nd" if category == "Nd" else None
        if name is None:
            continue
        ranges = categories[name]
        if ranges and start == ranges[-1][1] + 1:
            ranges[-1][1] = scalar
        else:
            ranges.append([start, scalar])
    assert pending is None
    assert [len(categories[name]) for name in ["L", "M", "Nd"]] == [684, 327, 72]
    payload = {
        "version": VERSION,
        "common": {"runs": runs, "singles": singles},
        "simpleOverrides": [[scalar, value[0]] for scalar, value in sorted(maps["S"].items())],
        "fullOverrides": [[scalar, value] for scalar, value in sorted(maps["F"].items())],
        "categories": categories,
    }
    encoded = json.dumps(payload, separators=(",", ":"), ensure_ascii=True)
    assert "'" not in encoded and "\\" not in encoded
    output = (
        "// SPDX-License-Identifier: Unicode-3.0\n"
        "// Generated by third_party/unicode17/generate.py. See its license and provenance.\n"
        "export const fontFamilyDataJSON =\n  '"
        + encoded
        + "';\n"
    ).encode()
    provenance = {
        "schema": 1,
        "unicodeVersion": VERSION,
        "dataLicense": "Unicode-3.0",
        "sources": sources,
        "generator": {
            "file": "third_party/unicode17/generate.py",
            "sha256": digest(Path(__file__).read_bytes()),
        },
        "output": {"file": "src/font-family-data.ts", "bytes": len(output), "sha256": digest(output)},
        "policy": {
            "simple": ["C", "S"],
            "css": ["C", "F"],
            "turkicMappings": False,
            "normalization": False,
            "categories": ["L", "M", "Nd"],
        },
        "counts": {
            "commonMappings": len(common),
            "commonRuns": len(runs),
            "commonSingles": len(singles),
            "simpleOverrides": len(maps["S"]),
            "fullOverrides": len(maps["F"]),
            "categoryRanges": {name: len(value) for name, value in categories.items()},
        },
    }
    return output, (json.dumps(provenance, indent=2) + "\n").encode()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Check bytes without writing output")
    options = parser.parse_args()
    generated, provenance = derive()
    for path, data in [
        (ROOT / "src/font-family-data.ts", generated),
        (DIRECTORY / "provenance.json", provenance),
    ]:
        if options.check:
            if path.read_bytes() != data:
                raise ValueError(f"Generated Unicode output is stale: {path.relative_to(ROOT)}")
        else:
            path.write_bytes(data)
    print("Unicode17 font-family data matches pinned sources.")


if __name__ == "__main__":
    main()
